    lines: [{ qty: 5, unitPrice: 1000, vatRate: 21 }],
  };
  const invoiceWithBulk = {
    lines: [{ qty: 10, unitPrice: 1000, vatRate: 21 }],
  };
  const totalsNoBulk = invoiceTotals(invoiceNoBulk);
  const totalsWithBulk = invoiceTotals(invoiceWithBulk);

  assert(totalsWithBulk.discount > totalsNoBulk.discount);
  assert(totalsWithBulk.total < totalsWithBulk.subtotal + totalsWithBulk.vat - totalsNoBulk.discount);
});

