test('lineDiscount with decimal discount percentage', () => {
  const line = { qty: 100, unitPrice: 1000, discountPercent: 12.5 };
  const discount = lineDiscount(line);
  assert(Number.isInteger(discount));
  const lineTotal = 100 * 1000;
  const firstDiscount = lineTotal * 12.5 / 100;
  const afterFirst = lineTotal - firstDiscount;
  const bulkDisc = afterFirst * 2.5 / 100;
  const expected = Math.round(firstDiscount + bulkDisc);
  assert.equal(discount, expected);
});

