import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, lineDiscount, lineVat, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';

test('createInvoice creates a draft invoice with valid customer, date, and lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  assert.equal(result.ok, true);
  assert.deepEqual(result.value, {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    terms: 'NET30',
    dueDate: '2026-11-06',
    status: 'draft',
    lines: [
      {
        sku: 'DES-HOUR',
        name: 'Design work (hour)',
        qty: 2,
        unitPrice: 8500,
        vatRate: 21,
        discountPercent: 5,
      },
    ],
  });
});

test('createInvoice normalizes lowercase customer ID', () => {
