  assert(lines[3].startsWith('VAT:'));
  const subtotal = 8500;
  const vat = subtotal * 21 / 100;
  const total = subtotal + vat;
  assert.equal(lines[4], `Total: €${(total / 100).toFixed(2)}`);
});

