    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  }).value;

  const text = renderInvoiceText(invoice);
  const expectedVat = 17000 * 21 / 100;
  const expectedVatFormatted = `€${(expectedVat / 100).toFixed(2)}`;

  assert(text.includes(`VAT: ${expectedVatFormatted}`));
});

test('renderInvoiceText with mixed VAT rates', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'PRINT-A4', qty: 100 },
    ],
  }).value;

  const text = renderInvoiceText(invoice);
  assert(text.includes('VAT:'));
  assert(text.includes('Total:'));
});

