  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  }).value;

  const text = renderInvoiceText(invoice);
  assert(text.includes('VAT: €0.00'));
  assert(text.includes('Total: €600.00'));
});

